export default async function(app){
 const [reactive,Portal,WebTileLayer,MosaicRule,RasterFunction]=await Promise.all([app.import('esri/core/reactiveUtils'),app.import('esri/portal/Portal'),app.import('esri/layers/WebTileLayer'),app.import('esri/layers/support/MosaicRule'),app.import('esri/layers/support/RasterFunction')]);
 const root=app.getMount('imagery-catalog'), right=app.getMount('imagery-functions'); const portal=new Portal({url:app.config.portalUrl});const sources=app.config.sources;
 const el=(tag,text,parent)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(parent)parent.append(n);return n;};
 const control=n=>{Object.assign(n.style,{boxSizing:'border-box',width:'100%',minWidth:'0',padding:'9px',border:'1px solid var(--calcite-color-border-2)',borderRadius:'4px',background:'var(--calcite-color-foreground-1)',color:'var(--calcite-color-text-1)',font:'inherit'});return n;};
 const field=(text,node,parent)=>{const label=el('label',text,parent);Object.assign(label.style,{display:'grid',gap:'5px',minWidth:'0'});label.append(control(node));return node;};
 const button=(text,parent,fn)=>{const n=control(el('button',text,parent));n.type='button';n.style.cursor='pointer';n.onclick=()=>Promise.resolve(fn()).catch(showError);return n;};
 const box=el('div',null,root);Object.assign(box.style,{display:'grid',gap:'12px',minWidth:'0',fontSize:'13px',color:'var(--calcite-color-text-1)'});
 const side=el('div',null,right);Object.assign(side.style,{display:'grid',gap:'10px',minWidth:'0',fontSize:'13px',color:'var(--calcite-color-text-1)'});
 const sideIntro=el('div','',side),sideStatus=el('small','',side),sideList=el('div',null,side);sideStatus.setAttribute('role','status');sideStatus.style.color='var(--calcite-color-text-2)';Object.assign(sideList.style,{display:'grid',gap:'7px'});
 const sourceSel=field('Servicio de imágenes',el('select'),box);for(const s of sources){const o=el('option',s.title,sourceSel);o.value=s.id;}
 const note=el('div','',box);note.style.color='var(--calcite-color-text-2)';
 const dates=el('div',null,box);Object.assign(dates.style,{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'8px'});
 const from=field('Desde',el('input'),dates);from.type='date';const to=field('Hasta',el('input'),dates);to.type='date';
 const cloud=field('Nubosidad máxima de la escena',el('select'),box);for(const v of [100,80,50,30,10,0]){const o=el('option',v===100?'Todas (incluye sin dato)':v+' %',cloud);o.value=String(v);}
 const render=field('Visualización',el('select'),box);const tip=el('small','',box);tip.style.lineHeight='1.5';tip.style.color='var(--calcite-color-text-2)';
 const row=el('div',null,box);Object.assign(row.style,{display:'flex',gap:'8px'});button('Actualizar área',row,()=>app.actions.invoke('imagery-refresh',{}));button('Restablecer filtros',row,()=>app.actions.invoke('imagery-filter',{from:'',to:'',cloud:100}));
 const status=el('div','Preparando catálogo…',box);status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.style.lineHeight='1.5';
 const activeText=el('div','Mapa: mosaico automático',box);Object.assign(activeText.style,{padding:'10px',borderLeft:'3px solid var(--calcite-color-brand)',background:'var(--calcite-color-foreground-2)',overflowWrap:'anywhere'});
 const compareRow=el('div',null,box);Object.assign(compareRow.style,{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'8px'});
 button('Guardar como A',compareRow,()=>app.actions.invoke('imagery-reference',{}));const toggle=button('Ver referencia A',compareRow,()=>app.actions.invoke('imagery-toggle',{}));toggle.disabled=true;
 const compareNote=el('small','Selecciona una imagen, guárdala como A y elige otra para alternar A/B.',box);
 const list=el('div',null,box);Object.assign(list.style,{display:'grid',gap:'7px'});
 const more=button('Cargar más',box,()=>app.actions.invoke('imagery-more',{}));more.hidden=true;
 const foot=el('small','Sentinel y Landsat requieren una cuenta ArcGIS habilitada. La nubosidad corresponde a la escena completa, no solo al área visible.',box);foot.style.lineHeight='1.5';foot.style.color='var(--calcite-color-text-2)';
 let source=sources[0],generation=0,items=[],catalog=[],total=0,next=0,busy=false,wayback=null,reference=null,showingA=false,selected=null,timer=null,disposed=false,lastView='',waybackCatalog=null;
 const resetLayer=s=>{if(!s.layerId)return;const l=app.layers[s.layerId];l.mosaicRule=l.defaultMosaicRule?.clone()||new MosaicRule({method:'attribute',sortField:'best',sortValue:'0',ascending:true});l.rasterFunction=new RasterFunction({functionName:'Natural Color for Visualization'});};
 for(const s of sources){if(s.layerId){resetLayer(s);app.layers[s.layerId].visible=s.id===source.id;}}
 const fmt=t=>t==null?'Sin fecha':new Date(t).toLocaleDateString('es-ES',{timeZone:'UTC'});
 function showError(e){if(disposed)return;busy=false;status.textContent='No se pudo completar la operación: '+(e.message||e)+'. Puedes reintentar o cambiar de servicio.';more.disabled=false;}
 function visibility(){for(const s of sources)if(s.layerId)app.layers[s.layerId].visible=s.id===source.id&&!showingA;if(wayback)wayback.visible=source.id==='wayback'&&!showingA;if(reference)reference.visible=showingA;toggle.textContent=showingA?'Volver a imagen B':'Ver referencia A';}
 function paintFunctions(){sideList.replaceChildren();const l=source.layerId?app.layers[source.layerId]:null;sideIntro.textContent=source.id==='wayback'?'World Imagery · Wayback: ediciones de teselas de mapa base. No ofrece plantillas de funciones ráster para aplicar aquí.':'Plantillas publicadas por '+source.title+'. Elige una para procesar el mosaico o la escena B visible.';sideStatus.textContent=l?(l.rasterFunctionInfos?.length||0)+' plantillas · Activa: '+(l.rasterFunction?.functionName||'Ninguna'):'No disponible para Wayback';if(!l)return;for(const f of l.rasterFunctionInfos||[]){const b=button(f.name,sideList,()=>app.actions.invoke('imagery-render',{name:f.name}));b.style.textAlign='left';b.style.overflowWrap='anywhere';b.setAttribute('aria-pressed',String(l.rasterFunction?.functionName===f.name));if(l.rasterFunction?.functionName===f.name)b.style.borderColor='var(--calcite-color-brand)';const detail=el('small',f.description||'Sin descripción',b);detail.style.display='block';detail.style.marginTop='4px';detail.style.lineHeight='1.4';detail.style.color='var(--calcite-color-text-2)';}const caution=el('small','Las plantillas «Raw for Analysis» producen valores de análisis; su aspecto en el visor puede diferir de las plantillas «for Visualization». La referencia A conserva la plantilla con la que se guardó.',sideList);caution.style.lineHeight='1.5';}
 function functions(){render.replaceChildren();const o=el('option','Color natural (predeterminado)',render);o.value='';const l=source.layerId?app.layers[source.layerId]:null;for(const f of l?.rasterFunctionInfos||[]){if(!/Visualization|with DRA|Classification/i.test(f.name))continue;const opt=el('option',f.name,render);opt.value=f.name;}cloud.parentElement.hidden=source.id==='wayback';render.parentElement.hidden=source.id==='wayback';cloud.disabled=source.id==='wayback';render.disabled=source.id==='wayback';foot.hidden=source.id==='wayback';note.textContent=source.note;tip.textContent=source.id==='wayback'?'Fecha de publicación, NO de captura. Son ediciones globales: pueden mostrar la misma imagen en esta zona. Esta versión no filtra cambios locales.':'Se listan escenas cuya huella intersecta el mapa; no implica cobertura completa. Sin fechas se consulta todo el archivo. La visualización rápida ofrece plantillas preparadas para el visor; el panel derecho muestra todas.';paintFunctions();}
 function summary(){return {source:source.id,total,loaded:items.length,catalogCount:catalog.length,uniqueCount:new Set(catalog.map(x=>x.id)).size,hasMore:next>0,firstId:items[0]?.id,secondId:items[1]?.id,firstDate:items[0]?.date,firstCloud:items[0]?.cloud,status:status.textContent,selected:selected?.id||null,cloudHidden:cloud.parentElement.hidden,visualizationHidden:render.parentElement.hidden,templateCount:source.layerId?app.layers[source.layerId].rasterFunctionInfos?.length:0};}
 function paint(){list.replaceChildren();items.forEach(item=>{const b=button('',list,()=>app.actions.invoke('imagery-select',{id:item.id}));b.style.textAlign='left';b.style.borderColor=selected?.id===item.id?'var(--calcite-color-brand)':'var(--calcite-color-border-2)';b.setAttribute('aria-pressed',String(selected?.id===item.id));el('strong',fmt(item.date)+(source.id==='wayback'?' · edición':''),b);const sub=el('div',source.id==='wayback'?'Mapa base archivado':(item.cloud==null?'Nubes: sin dato':'Nubes: '+Number(item.cloud).toFixed(1)+' %')+' · '+(item.platform||''),b);sub.style.marginTop='4px';sub.style.color='var(--calcite-color-text-2)';const name=el('small',item.name,b);name.style.overflowWrap='anywhere';});more.hidden=next<=0;more.disabled=busy;status.textContent=total===0?'No hay resultados con estos filtros'+(source.id==='wayback'?'.':' en el área visible.'):items.length+' de '+total.toLocaleString('es-ES')+(source.id==='wayback'?' ediciones globales':' escenas en el área visible')+' · más recientes primero';}
 function page(){items.push(...catalog.slice(items.length,items.length+40));next=items.length<catalog.length?items.length:-1;busy=false;paint();return summary();}
 async function refresh(){const mine=++generation;busy=true;items=[];catalog=[];next=0;total=0;list.replaceChildren();more.hidden=true;status.textContent='Consultando imágenes para esta vista…';if(from.value&&to.value&&from.value>to.value)throw Error('La fecha inicial debe ser anterior a la final');const s=source;let rows=[];
 if(s.id==='wayback'){if(!waybackCatalog){const all=[];let start=1;do{const r=await portal.queryItems({query:'group:'+app.config.waybackGroup+' AND type:WMTS AND NOT title:Metadata',num:100,start,sortField:'title',sortOrder:'desc'});all.push(...r.results);start=r.nextQueryParams?.start||-1;if(mine!==generation||disposed)return {stale:true};if(all.length>=1000&&start>0)throw Error('El catálogo supera 1000 ediciones; no se mostrará como completo');}while(start>0);waybackCatalog=all.map(p=>{const d=p.title.match(/\d{4}-\d{2}-\d{2}/)?.[0];return {id:p.id,date:d?Date.parse(d):null,name:p.title,url:p.url,portalItem:p};});}rows=waybackCatalog.filter(p=>(!from.value||p.date>=Date.parse(from.value))&&(!to.value||p.date<Date.parse(to.value)+86400000));
 }else{const l=app.layers[s.layerId];await l.load();if(mine!==generation)return {stale:true};const extent=app.view.extent?.clone();if(!extent){busy=false;status.textContent='Esperando al mapa…';return summary();}const clauses=['acquisitiondate IS NOT NULL'];if(from.value)clauses.push("acquisitiondate >= timestamp '"+from.value+" 00:00:00'");if(to.value){const end=new Date(Date.parse(to.value)+86400000).toISOString().slice(0,10);clauses.push("acquisitiondate < timestamp '"+end+" 00:00:00'");}if(Number(cloud.value)<100)clauses.push('cloudcover >= 0 AND cloudcover <= '+Number(cloud.value));const ids=[...new Set(await l.queryObjectIds({where:clauses.join(' AND '),geometry:extent,spatialRelationship:'intersects'}))];if(mine!==generation||disposed)return {stale:true};if(ids.length>16000)throw Error('Hay '+ids.length.toLocaleString('es-ES')+' escenas. Acerca el mapa o acota las fechas para consultar hasta 16.000 por vista');const byId=new Map();for(let start=0;start<ids.length;start+=500){const batch=ids.slice(start,start+500);const r=await l.queryRasters({objectIds:batch,outFields:['objectid','name','acquisitiondate','cloudcover',s.id==='sentinel'?'platform':'sensorname'],returnGeometry:false});if(mine!==generation||disposed)return {stale:true};for(const f of r.features){const a=f.attributes;byId.set(a[l.objectIdField],{id:a[l.objectIdField],date:a.acquisitiondate,name:a.name,cloud:a.cloudcover,platform:a.platform||a.sensorname});}status.textContent='Leyendo metadatos: '+byId.size+' de '+ids.length+' escenas…';}if(byId.size!==ids.length)throw Error('El servicio devolvió '+byId.size+' de '+ids.length+' escenas. Actualiza para reintentar; no se mostrará un catálogo incompleto');rows=[...byId.values()];}
 if(mine!==generation||disposed)return {stale:true};catalog=rows.sort((a,b)=>(b.date||0)-(a.date||0)||String(b.id).localeCompare(String(a.id)));total=catalog.length;return page();}
 app.actions.register('imagery-refresh',async()=>{try{return await refresh();}catch(e){showError(e);return {error:e.message,...summary()};}});
 app.actions.register('imagery-filter',async(p)=>{if(p.from!==undefined)from.value=p.from;if(p.to!==undefined)to.value=p.to;if(p.cloud!==undefined)cloud.value=String(p.cloud);return app.actions.invoke('imagery-refresh',{});});
 app.actions.register('imagery-more',()=>{if(busy||next<=0)return summary();return page();});
 app.actions.register('imagery-source',async({id})=>{const s=sources.find(x=>x.id===id);if(!s)throw Error('Servicio desconocido');source=s;sourceSel.value=id;selected=null;showingA=false;resetLayer(s);functions();visibility();activeText.textContent=id==='wayback'?(wayback?'Mapa: '+wayback.title:'Selecciona una edición de Wayback'):'Mapa: mosaico automático de '+source.title;return app.actions.invoke('imagery-refresh',{});});
 app.actions.register('imagery-select',async({id})=>{const item=items.find(x=>String(x.id)===String(id));if(!item)throw Error('La imagen ya no pertenece al catálogo visible');const mine=generation;const s=source;showingA=false;if(s.id==='wayback'){const data=await item.portalItem.fetchData();if(mine!==generation||disposed)return {stale:true};const template=data?.templateUrl||item.url;if(!template?.includes('{level}'))throw Error('Esta edición no ofrece una plantilla de teselas compatible');const candidate=new WebTileLayer({urlTemplate:template,tileInfo:data?.tileInfo,fullExtent:data?.fullExtent,title:item.name,copyright:item.portalItem.accessInformation||'Esri y la comunidad GIS',id:'explorer-wayback'});await candidate.load();if(mine!==generation||disposed){candidate.destroy();return {stale:true};}if(wayback){app.map.remove(wayback);wayback.destroy();}wayback=candidate;item.url=template;app.map.add(wayback);}else{const l=app.layers[s.layerId];l.mosaicRule=new MosaicRule({method:'lock-raster',lockRasterIds:[Number(item.id)],operation:'first'});}selected=item;visibility();activeText.textContent='B · '+s.title+' · '+fmt(item.date)+(s.id==='wayback'?' (publicación)':' (captura)');paint();return {source:s.id,id:item.id,date:item.date,mosaicRule:s.layerId?app.layers[s.layerId].mosaicRule.toJSON():null,url:s.id==='wayback'?item.url:null};});
 app.actions.register('imagery-render',({name})=>{const l=source.layerId?app.layers[source.layerId]:null;if(!l)throw Error('Las ediciones Wayback no admiten plantillas ráster');if(name&&!l.rasterFunctionInfos.some(f=>f.name===name))throw Error('Plantilla no disponible en este servicio');l.rasterFunction=new RasterFunction({functionName:name||'Natural Color for Visualization'});render.value=[...render.options].some(o=>o.value===name)?name:'';paintFunctions();return {layerId:l.id,functionName:l.rasterFunction?.functionName,selectedRasterIds:l.mosaicRule?.lockRasterIds||[],visible:l.visible};});
 app.actions.register('imagery-reference',()=>{if(!selected)throw Error('Selecciona primero una imagen del catálogo');if(reference){app.map.remove(reference);reference.destroy();}reference=(source.id==='wayback'?wayback:app.layers[source.layerId]).clone();reference.id='explorer-reference';reference.title='Referencia A · '+fmt(selected.date);reference.visible=false;app.map.add(reference);showingA=false;toggle.disabled=false;compareNote.textContent='A · '+source.title+' · '+fmt(selected.date)+'. Elige otra imagen y alterna A/B sin cambiar de área.';visibility();return {reference:reference.title};});
 app.actions.register('imagery-toggle',()=>{if(!reference)return {available:false};showingA=!showingA;visibility();return {showing:showingA?'A':'B',reference:reference.title};});
 sourceSel.onchange=()=>app.actions.invoke('imagery-source',{id:sourceSel.value}).catch(showError);for(const n of [from,to,cloud])n.onchange=()=>app.actions.invoke('imagery-refresh',{}).catch(showError);render.onchange=()=>app.actions.invoke('imagery-render',{name:render.value}).catch(showError);
 const watch=reactive.watch(()=>[app.view.stationary,app.view.extent?.xmin,app.view.extent?.ymin,app.view.scale],([stationary])=>{if(!stationary){generation++;return;}const key=JSON.stringify(app.view.extent?.toJSON());if(key===lastView)return;lastView=key;clearTimeout(timer);timer=setTimeout(()=>app.actions.invoke('imagery-refresh',{}).catch(showError),450);});
 app.onCleanup(()=>{disposed=true;generation++;watch.remove();clearTimeout(timer);for(const l of [wayback,reference])if(l){app.map.remove(l);l.destroy();}root.replaceChildren();right.replaceChildren();});functions();visibility();timer=setTimeout(()=>app.actions.invoke('imagery-refresh',{}).catch(showError),100);
}